126	     * Handles exception thrown by Bean Validation on controller methods parameters
127	     *
128	     * @param e The {@link MethodArgumentNotValidException} to be handled
129	     * @param request {@link HttpServletRequest} object referring to the current request.
130	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
131	     */
132	    @ExceptionHandler(MethodArgumentNotValidException.class)
133	    @ResponseBody
134	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
135	        HttpStatus status = HttpStatus.BAD_REQUEST;
136	        BindingErrorsResponse errors = new BindingErrorsResponse();
137	        BindingResult bindingResult = e.getBindingResult();
138	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
139	        if (bindingResult.hasErrors()) {
140	            errors.addAllErrors(bindingResult);
141	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
142	                .map(fieldError -> {
143	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
144	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
145	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
146	                        fieldError.getField(),
147	                        defaultMessage,
148	                        rejectedValue);
149	                    return new ValidationMessageDto(message)
150	                        .putAdditionalProperty("field", fieldError.getField())
151	                        .putAdditionalProperty("rejectedValue", rejectedValue)
152	                        .putAdditionalProperty("defaultMessage", defaultMessage);
153	                })
154	                .toList();
155	            logger.debug("Validation error at {} {}: {}",
156	                request.getMethod(),
157	                request.getRequestURI(),
158	                bindingResult.getFieldErrors());
159	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
160	            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
161	                .map(fieldError -> fieldError.getField())
162	                .distinct()
163	                .toList());
