20	
21	/**
22	 * Normalises a postal address to a canonical form for storage and comparison.
23	 *
24	 * <p>Whitespace is trimmed and collapsed, the value is upper-cased, and common
25	 * street-type abbreviations are expanded as whole words ({@code ST -> STREET},
26	 * {@code RD -> ROAD}, {@code AVE -> AVENUE}). A value that is blank (only
27	 * whitespace) normalises to the empty string.
28	 */
29	public abstract class Addresses {
30	
31	    private static final Map<String, String> ABBREVIATIONS =
32	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
33	
34	    /**
35	     * @param raw the raw address input, may be {@code null}
36	     * @return the normalised address, or {@code null} when {@code raw} is {@code null}
37	     */
38	    public static String normalize(String raw) {
